def babylonian_squareroot(number):
    if number < 0:
        raise ValueError("Cannot compute the square root of a negative number.")
    if number == 0:
        return 0.0

    guess = number / 2.0
    tolerance = 1e-12

    while True:
        next_guess = 0.5 * (guess + number / guess)
        if abs(guess - next_guess) <= tolerance * max(1.0, abs(next_guess)):
            return next_guess
        guess = next_guess

