def cal_sum(n):
    if n < 0:
        return 0
    # Base values
    P = [3, 0, 2]
    if n < len(P):
        return sum(P[:n+1])
    # Compute up to n
    for i in range(3, n + 1):
        P.append(P[i - 2] + P[i - 3])
    return sum(P[:n + 1])

