import numbers

def _to_float(value):
    """
    Convert a numeric value or a string representation of a real number
    to a float. The string can contain either '.' or ',' as the decimal
    separator.
    """
    if isinstance(value, numbers.Number):
        return float(value)
    if isinstance(value, str):
        # Replace comma with dot if present
        cleaned = value.replace(',', '.')
        try:
            return float(cleaned)
        except ValueError:
            raise ValueError(f"String '{value}' is not a valid number.")
    raise TypeError(f"Unsupported type: {type(value)}")


def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or .
    """
    # Convert both to float for comparison
    try:
        fa = _to_float(a)
        fb = _to_float(b)
    except Exception as e:
        raise ValueError(f"Cannot compare values: {e}")

    if fa > fb:
        return a
    if fb > fa:
