import heapq

def large_product(nums1, nums2, N):
    """
    Return the N largest products formed by multiplying one element from nums1 and one element from nums2.
    If N is greater than the total number of possible products, all products are returned.
    The result is sorted in descending order.
    """
    # Sanity checks
    if not nums1 or not nums2:
        return []

    total = len(nums1) * len(nums2)
    # If N exceeds total products, adjust it
    if N >= total:
        return sorted([a * b for a in nums1 for b in nums2], reverse=True)

    # Use a min-heap of size N to keep track of largest products
    min_heap = []
    for a in nums1:
        for b in nums2:
            prod = a * b
            if len(min_heap) < N:
                heapq.heappush(min_heap, prod)
            else:
                # min_heap[0] is the smallest in the current top N
                if prod > min_heap[0]:
                    heapq.heapreplace(min_heap, prod)

    # Extract elements from heap and sort descending
    return sorted(min_heap, reverse=True)

