def dict_depth(d):
    """
    Return the maximum depth of nested dictionaries in `d`.

    A dictionary with no nested dictionaries has depth 1.
    If a value is not a dictionary, it does not contribute to depth.
    """
    if not isinstance(d, dict):
        raise TypeError("Input must be a dictionary")

    def _depth(current):
        if not isinstance(current, dict) or not current:
            return 1
        max_subdepth = 0
        for v in current.values():
            if isinstance(v, dict):
                subdepth = _depth(v)
                if subdepth > max_subdepth:
                    max_subdepth = subdepth
        return 1 + max_subdepth

    return _depth(d)

def dict_depth(d):
    if isinstance(d, dict):
        return 1 + (max(map(dict_depth, d.values())) if d else 0)
    return 0

