def set_left_most_unset_bit(n: int) -> int:
    """Return n with its most significant 0 bit set to 1.

    If all bits up to the current most significant bit are 1,
    the function sets the next higher bit.
    """
    if n < 0:
        raise ValueError("n must be non‑negative")

    bit_len = n.bit_length()
    # Scan from most significant bit downwards
    for i in range(bit_len - 1, -1, -1):
        if (n >> i) & 1 == 0:
            return n | (1 << i)

    # All lower bits are 1 – set the next higher bit
    return n | (1 << bit_len)

