def dict_depth(d):
    """Return the maximum depth of nested dictionaries.

    An empty dictionary has depth 1. A non-dictionary value has depth 0.
    """
    if not isinstance(d, dict):
        return 0
    if not d:
        return 1
    max_subdepth = 0
    for v in d.values():
        subdepth = dict_depth(v)
        if subdepth > max_subdepth:
            max_subdepth = subdepth
    return 1 + max_subdepth

