def set_left_most_unset_bit(n: int) -> int:
    """
    Set the most significant bit that is currently 0 in the binary representation of n.
    If all bits up to the current most significant bit are 1, a new higher-order bit is added.
    The function works for non‑negative integers.

    Examples:
        0b1011 (11) -> 0b1111 (15)  -> leftmost unset bit (bit 2) is set.
        0b1111 (15) -> 0b11111 (31) -> all lower bits are 1, so bit 4 is set.
        0b0 (0) -> 0b1 (1)           -> first bit is set.
    """
    if n < 0:
        raise ValueError("n must be non‑negative")

    # Handle zero separately (no bits set)
    if n == 0:
        return 1

    # Find index of the current most significant bit
    msb_index = n.bit_length() - 1  # zero‑based index

    # Search downward for a 0 bit
    for i in range(msb_index, -1, -1):
        if (n >> i) & 1 == 0:
            return n | (1 << i)

    # All lower bits are 1, set the next higher bit
    return n | (1 << (msb_index + 1))

