def is_undulating(n: int) -> bool:
    """
    Return True if the decimal representation of n is an undulating number.
    A number is undulating if its digits alternate strictly between increasing
    and decreasing.  The first step may be either rising or falling.
    Numbers with fewer than 3 digits are not considered undulating.
    """
    if n < 0:
        n = -n
    s = str(n)
    if len(s) < 3:
        return False
    # Determine initial direction by first two differing digits
    i = 0
    while i < len(s)-1 and s[i] == s[i+1]:
        i += 1
    if i == len(s)-1:
        # all digits equal
        return False
    prev = int(s[i])
    cur = int(s[i+1])
    increasing = cur > prev
    # Continue scanning
    for j in range(i+2, len(s)):
        prev = cur
        cur = int(s[j])
        if cur == prev:
            return False
        if increasing:
            if cur <= prev:
                return False
        else:
            if cur >= prev:
                return False
        increasing = not increasing
    return True

