import math

def is_prime(n: int) -> bool:
    """Return True if n is a prime number, False otherwise."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def is_multiply_prime(a: int) -> bool:
    """Return True if a is the product of exactly three prime numbers (not necessarily distinct).
    The number a is guaranteed to be less than 100.
    Example:
        is_multiply_prime(30) == True   # 30 = 2 * 3 * 5
    """
    # Quick check for negative or zero
    if a <= 0:
        return False

    # Count prime factors using trial division
    count = 0
    temp = a
    for p in range(2, int(math.isqrt(temp)) + 1):
        while temp % p == 0 and is_prime(p):
            count += 1
            temp //= p
            if count > 3:
                return False
    # If remaining temp > 1 it is a prime factor
    if temp > 1:
        count += 1

    return count == 3

