def set_left_most_unset_bit(n):
    """
    Set the leftmost unset (0) bit in the binary representation of n.
    If all bits up to the most significant 1 are set, set the next higher bit.
    """
    if n < 0:
        raise ValueError("n must be a non-negative integer")
    # Determine the highest position to check: one more than the current bit length
    max_pos = n.bit_length()
    for pos in range(max_pos, -1, -1):
        if (n >> pos) & 1 == 0:
            return n | (1 << pos)
    # Should never reach here because loop covers pos = 0
    return n

