import re

def parse_record(line):
    """
    Parse a record line into a dict.
    - Fields are separated by ";". Empty fields are ignored.
    - A field is either key=value or a bare key, which maps to True.
    - Keys and unquoted values have surrounding whitespace removed.
    - A value may be wrapped in double quotes: inside the quotes ";" is literal, \\" is an escaped
      quote, and the text is kept exactly (no trimming). The quotes themselves are removed.
    - If a key repeats, the later value wins.

    parse_record('name=Ana; city = Lyon') == {"name": "Ana", "city": "Lyon"}
    parse_record('note="a;b"; urgent') == {"note": "a;b", "urgent": True}
    """
    result = {}
    field = []
    in_quote = False
    escape_next = False

    # First, split the line into raw fields respecting quoted semicolons
    raw_fields = []
    for ch in line:
        if escape_next:
            field.append(ch)
            escape_next = False
            continue
        if in_quote:
            if ch == '\\':
                escape_next = True
            elif ch == '"':
                in_quote = False
                field.append(ch)  # keep the closing quote for later removal
            else:
                field.append(ch)
        else:
            if ch == ';':
                raw_fields.append(''.join(field))
                field = []
            elif ch == '"':
                in_quote = True
                field.append(ch)
            else:
                field.append(ch)
    if field:
        raw_fields.append(''.join(field))

    for raw in raw_fields:
        if not raw.strip():
            continue
        key, value = None, None
        if '=' in raw:
            k, v = raw.split('=', 1)
            key = k.strip()
            v = v.strip()
            if v.startswith('"') and v.endswith('"'):
                # Remove outer quotes and unescape inner ones
                inner = v[1:-1]
                inner = inner.replace(r'\"', '"')
                value = inner
            else:
                value = v.strip()
        else:
            key = raw.strip()
            value = True
        if key:
            result[key] = value
    return result

